tool_input.command:
cat >> crates/kahvi-builtins/src/support/intl_number_format.rs <<'EOF'

/// An Intl mathematical value: a mathematical value together with
/// ~positive-infinity~, ~negative-infinity~, ~not-a-number~ and
/// ~negative-zero~. A finite value is exact: the decimal digits of its
/// absolute value and its sign (never negative zero).
#[derive(Debug, Clone)]
pub(crate) enum IntlMV {
    NotANumber,
    PositiveInfinity,
    NegativeInfinity,
    NegativeZero,
    Finite {
        negative: bool,
        abs: icu::decimal::input::Decimal,
    },
}

impl IntlMV {
    /// A finite mathematical value from its sign and absolute value; a
    /// negative zero is ~negative-zero~.
    fn finite(negative: bool, abs: icu::decimal::input::Decimal) -> IntlMV {
        if negative && abs.is_zero() {
            IntlMV::NegativeZero
        } else {
            IntlMV::Finite { negative, abs }
        }
    }
}

fn is_js_white_space_or_line_terminator(c: char) -> bool {
    (c.is_whitespace() && c != '\u{85}') || c == '\u{FEFF}'
}

/// The mathematical value of the digits of _digits_ in _radix_, as a decimal.
fn radix_digits_to_decimal(digits: &str, radix: u32) -> Option<icu::decimal::input::Decimal> {
    // Little-endian base-10 digits.
    let mut dec: Vec<u8> = vec![0];
    for c in digits.chars() {
        let mut carry = c.to_digit(radix)?;
        for d in dec.iter_mut() {
            let v = u32::from(*d) * radix + carry;
            *d = (v % 10) as u8;
            carry = v / 10;
        }
        while carry > 0 {
            dec.push((carry % 10) as u8);
            carry /= 10;
        }
    }
    let text: String = dec.iter().rev().map(|d| char::from(b'0' + d)).collect();
    icu::decimal::input::Decimal::try_from_str(&text).ok()
}

/// The StringIntlMV of ParseText(_text_, |StringNumericLiteral|), or *None*
/// when the text is not a StringNumericLiteral.
fn string_intl_mv(text: &str) -> Option<IntlMV> {
    use icu::decimal::input::Decimal;
    let s = text.trim_matches(is_js_white_space_or_line_terminator);
    // The empty StringNumericLiteral has the mathematical value 0.
    if s.is_empty() {
        return Some(IntlMV::Finite {
            negative: false,
            abs: Decimal::from(0u8),
        });
    }
    // Hex, octal and binary integer literals take no sign.
    let radix = match s.get(..2) {
        Some("0x" | "0X") => Some(16),
        Some("0o" | "0O") => Some(8),
        Some("0b" | "0B") => Some(2),
        _ => None,
    };
    if let Some(radix) = radix {
        let abs = radix_digits_to_decimal(&s[2..], radix).filter(|_| s.len() > 2)?;
        return Some(IntlMV::finite(false, abs));
    }
    let (negative, body) = match s.as_bytes()[0] {
        b'-' => (true, &s[1..]),
        b'+' => (false, &s[1..]),
        _ => (false, s),
    };
    if body == "Infinity" {
        return Some(if negative {
            IntlMV::NegativeInfinity
        } else {
            IntlMV::PositiveInfinity
        });
    }
    // StrUnsignedDecimalLiteral: digits [. digits] [e [+-] digits], or . digits [e ...].
    let (mantissa, exponent) = match body.find(['e', 'E']) {
        Some(i) => (&body[..i], Some(&body[i + 1..])),
        None => (body, None),
    };
    let (int_part, frac_part) = match mantissa.split_once('.') {
        Some((i, f)) => (i, f),
        None => (mantissa, ""),
    };
    let all_digits = |t: &str| t.bytes().all(|b| b.is_ascii_digit());
    if !all_digits(int_part) || !all_digits(frac_part) || (int_part.is_empty() && frac_part.is_empty())
    {
        return None;
    }
    let exp: i64 = match exponent {
        None => 0,
        Some(e) => {
            let digits = e.strip_prefix(['+', '-']).unwrap_or(e);
            if digits.is_empty() || !all_digits(digits) {
                return None;
            }
            // Beyond i32 the value is outside any Number anyway.
            let magnitude = digits.parse::<i64>().unwrap_or(i64::from(i32::MAX));
            if e.starts_with('-') { -magnitude } else { magnitude }
        }
    };
    let int_part = if int_part.is_empty() { "0" } else { int_part };
    let mut abs = Decimal::try_from_str(&format!("{int_part}.{frac_part}")).ok()?;
    if !abs.is_zero() {
        match i16::try_from(exp) {
            Ok(exp) => abs.multiply_pow10(exp),
            // An exponent outside i16 is outside the range of any Number.
            Err(_) if exp > 0 => {
                return Some(if negative {
                    IntlMV::NegativeInfinity
                } else {
                    IntlMV::PositiveInfinity
                });
            }
            Err(_) => return Some(IntlMV::finite(negative, Decimal::from(0u8))),
        }
    }
    Some(IntlMV::finite(negative, abs))
}

/// ToIntlMathematicalValue ( _value_ )
pub(crate) fn to_intl_mathematical_value(agent: &mut Agent, value: Value) -> JsResult<IntlMV> {
    // 1. Let _primValue_ be ? ToPrimitive(_value_, ~number~).
    let prim_value = ops::to_primitive(agent, value, ops::PreferredType::Number)?;
    let str: String;
    // 2. If _primValue_ is a BigInt, return ℝ(_primValue_).
    if let Value::BigInt(b) = prim_value {
        let text = ops::bigint::to_js_string(agent, b, 10);
        str = agent.str_lossy(text);
    } else if let Value::String(s) = prim_value {
        // 3. If _primValue_ is a String, then
        //    a. Let _str_ be _primValue_.
        str = agent.str_lossy(s);
    } else {
        // 4. Else,
        //    a. Let _x_ be ? ToNumber(_primValue_).
        let x = ops::to_number(agent, prim_value)?;
        //    b. If _x_ is *-0*_𝔽, return ~negative-zero~.
        if x == 0.0 && x.is_sign_negative() {
            return Ok(IntlMV::NegativeZero);
        }
        //    c. Let _str_ be Number::toString(_x_, 10).
        let text = ops::number_to_js_string(agent, x);
        str = agent.str_lossy(text);
    }
    // 5. Let _text_ be StringToCodePoints(_str_).
    // 6. Let _literal_ be ParseText(_text_, |StringNumericLiteral|).
    // 7. If _literal_ is a List of errors, return ~not-a-number~.
    // 8. Let _intlMV_ be the StringIntlMV of _literal_.
    let Some(intl_mv) = string_intl_mv(&str) else {
        return Ok(IntlMV::NotANumber);
    };
    // 9. If _intlMV_ is a mathematical value, then
    if let IntlMV::Finite { negative, abs } = &intl_mv {
        // a. Let _rounded_ be RoundMVResult(abs(_intlMV_)).
        // The nearest Number to the value (an implementation-defined choice
        // for values with more than 20 significant digits).
        let rounded: f64 = abs.to_string().parse().unwrap_or(f64::INFINITY);
        // b. If _rounded_ is *+∞*_𝔽 and _intlMV_ < 0, return ~negative-infinity~.
        // c. If _rounded_ is *+∞*_𝔽, return ~positive-infinity~.
        if rounded.is_infinite() {
            return Ok(if *negative {
                IntlMV::NegativeInfinity
            } else {
                IntlMV::PositiveInfinity
            });
        }
        // d. If _rounded_ is *+0*_𝔽 and _intlMV_ < 0, return ~negative-zero~.
        // e. If _rounded_ is *+0*_𝔽, return 0.
        if rounded == 0.0 {
            return Ok(IntlMV::finite(*negative, icu::decimal::input::Decimal::from(0u8)));
        }
    }
    // 10. Return _intlMV_.
    Ok(intl_mv)
}

/// The Record returned by FormatNumericToString.
pub(crate) struct FormatNumericToStringResult {
    /// [[RoundedNumber]]
    pub rounded_number: IntlMV,
    /// [[FormattedString]]
    pub formatted_string: String,
}

/// The Records returned by ToRawPrecision and ToRawFixed.
struct RawResult {
    /// [[FormattedString]]
    formatted_string: String,
    /// [[RoundedNumber]]
    rounded_number: icu::decimal::input::Decimal,
    /// [[IntegerDigitsCount]]
    integer_digits_count: usize,
    /// [[RoundingMagnitude]]
    rounding_magnitude: i64,
}

type UnsignedRoundingMode = fixed_decimal_rounding::UnsignedRoundingMode;

/// GetUnsignedRoundingMode ( _roundingMode_, _sign_ ): ICU4X names the
/// unsigned modes ~zero~ Trunc, ~infinity~ Expand, ~half-zero~ HalfTrunc,
/// ~half-infinity~ HalfExpand and ~half-even~ HalfEven.
fn get_unsigned_rounding_mode(rounding_mode: &str, negative: bool) -> Option<UnsignedRoundingMode> {
    use UnsignedRoundingMode::*;
    Some(match (rounding_mode, negative) {
        ("ceil", false) | ("expand", _) => Expand,
        ("ceil", true) | ("trunc", _) => Trunc,
        ("floor", false) => Trunc,
        ("floor", true) => Expand,
        ("halfCeil", false) | ("halfExpand", _) => HalfExpand,
        ("halfCeil", true) | ("halfTrunc", _) => HalfTrunc,
        ("halfFloor", false) => HalfTrunc,
        ("halfFloor", true) => HalfExpand,
        ("halfEven", _) => HalfEven,
        _ => return None,
    })
}

fn position(agent: &mut Agent, p: i64) -> JsResult<i16> {
    match i16::try_from(p) {
        Ok(p) => Ok(p),
        Err(_) => Err(agent.not_implemented("Intl.NumberFormat: digit position beyond ICU4X's range")),
    }
}

fn digits_between(x: &icu::decimal::input::Decimal, from: i64, to: i64) -> String {
    (to..=from)
        .rev()
        .map(|m| char::from(b'0' + x.digit_at(m as i16)))
        .collect()
}

/// ToRawPrecision ( _x_, _minPrecision_, _maxPrecision_, _unsignedRoundingMode_ )
fn to_raw_precision(
    agent: &mut Agent,
    x: &icu::decimal::input::Decimal,
    min_precision: i64,
    max_precision: i64,
    unsigned_rounding_mode: UnsignedRoundingMode,
) -> JsResult<RawResult> {
    use icu::decimal::input::Decimal;
    // 1. Let _p_ be _maxPrecision_.
    let p = max_precision;
    let mut m: String;
    let e: i64;
    let x_final: Decimal;
    // 2. If _x_ = 0, then
    if x.is_zero() {
        // a. Let _m_ be the String consisting of _p_ occurrences of the code unit 0x0030 (DIGIT ZERO).
        m = "0".repeat(p as usize);
        // b. Let _e_ be 0.
        e = 0;
        // c. Let _xFinal_ be 0.
        x_final = Decimal::from(0u8);
    } else {
        // 3. Else,
        // a-c. Round _x_ to _p_ significant digits (_n1_/_r1_ below, _n2_/_r2_ above) with the unsigned rounding mode.
        let e1 = i64::from(x.nonzero_magnitude_start());
        let pos = position(agent, e1 - p + 1)?;
        let mut rounded = x.clone();
        rounded.round_with_mode(pos, unsigned_rounding_mode);
        x_final = rounded;
        // d-e. The exponent of the chosen value (_e2_ = _e1_ + 1 when it rounded up to a power of ten).
        e = i64::from(x_final.nonzero_magnitude_start());
        // f. Let _m_ be the String consisting of the digits of the decimal representation of _n_ (in order, with no leading zeroes).
        m = digits_between(&x_final, e, e - p + 1);
    }
    let int: usize;
    // 4. If _e_ ≥ (_p_ - 1), then
    if e >= p - 1 {
        // a. Set _m_ to the string-concatenation of _m_ and _e_ - _p_ + 1 occurrences of the code unit 0x0030 (DIGIT ZERO).
        m.push_str(&"0".repeat((e - p + 1) as usize));
        // b. Let _int_ be _e_ + 1.
        int = (e + 1) as usize;
    } else if e >= 0 {
        // 5. Else if _e_ ≥ 0, then
        // a. Set _m_ to the string-concatenation of the first _e_ + 1 code units of _m_, the code unit 0x002E (FULL STOP), and the remaining _p_ - (_e_ + 1) code units of _m_.
        let split = (e + 1) as usize;
        m = format!("{}.{}", &m[..split], &m[split..]);
        // b. Let _int_ be _e_ + 1.
        int = split;
    } else {
        // 6. Else,
        // a. Assert: _e_ < 0.
        // b. Set _m_ to the string-concatenation of *"0."*, -(_e_ + 1) occurrences of the code unit 0x0030 (DIGIT ZERO), and _m_.
        m = format!("0.{}{}", "0".repeat((-(e + 1)) as usize), m);
        // c. Let _int_ be 1.
        int = 1;
    }
    // 7. If _m_ contains the code unit 0x002E (FULL STOP) and _maxPrecision_ > _minPrecision_, then
    if m.contains('.') && max_precision > min_precision {
        // a. Let _cut_ be _maxPrecision_ - _minPrecision_.
        let mut cut = max_precision - min_precision;
        // b. Repeat, while _cut_ > 0 and the last code unit of _m_ is 0x0030 (DIGIT ZERO),
        while cut > 0 && m.ends_with('0') {
            // i. Remove the last code unit from _m_.
            m.pop();
            // ii. Set _cut_ to _cut_ - 1.
            cut -= 1;
        }
        // c. If the last code unit of _m_ is 0x002E (FULL STOP), then
        if m.ends_with('.') {
            // i. Remove the last code unit from _m_.
            m.pop();
        }
    }
    // 8. Return the Record { [[FormattedString]]: _m_, [[RoundedNumber]]: _xFinal_, [[IntegerDigitsCount]]: _int_, [[RoundingMagnitude]]: _e_–_p_+1 }.
    Ok(RawResult {
        formatted_string: m,
        rounded_number: x_final,
        integer_digits_count: int,
        rounding_magnitude: e - p + 1,
    })
}

/// ToRawFixed ( _x_, _minFraction_, _maxFraction_, _roundingIncrement_, _unsignedRoundingMode_ )
fn to_raw_fixed(
    agent: &mut Agent,
    x: &icu::decimal::input::Decimal,
    min_fraction: i64,
    max_fraction: i64,
    rounding_increment: i64,
    unsigned_rounding_mode: UnsignedRoundingMode,
) -> JsResult<RawResult> {
    use icu::decimal::input::Decimal;
    // 1. Let _f_ be _maxFraction_.
    let f = max_fraction;
    // 2-5. Let _n_ be the multiple of _roundingIncrement_ at 10^-_f_ chosen by ApplyUnsignedRoundingMode.
    // The increment is base × 10^k with base 1, 2, 5 or 25, which ICU4X rounds at position k - f.
    let mut base = rounding_increment;
    let mut k = 0;
    while base % 10 == 0 {
        base /= 10;
        k += 1;
    }
    let increment = match base {
        1 => RoundingIncrement::MultiplesOf1,
        2 => RoundingIncrement::MultiplesOf2,
        5 => RoundingIncrement::MultiplesOf5,
        25 => RoundingIncrement::MultiplesOf25,
        _ => return Err(agent.throw_range_error("invalid roundingIncrement")),
    };
    let pos = position(agent, k - f)?;
    let mut x_final: Decimal = x.clone();
    x_final.round_with_mode_and_increment(
        pos,
        SignedRoundingMode::Unsigned(unsigned_rounding_mode),
        increment,
    );
    // 6. If _n_ = 0, let _m_ be *"0"*. Otherwise, let _m_ be the String consisting of the digits of the decimal representation of _n_ (in order, with no leading zeroes).
    let top = if x_final.is_zero() {
        0
    } else {
        i64::from(x_final.nonzero_magnitude_start()).max(0)
    };
    let mut m = digits_between(&x_final, top, -f).trim_start_matches('0').to_string();
    if m.is_empty() {
        m.push('0');
    }
    let int: usize;
    // 7. If _f_ ≠ 0, then
    if f != 0 {
        // a. Let _k_ be the length of _m_.
        let mut k = m.len() as i64;
        // b. If _k_ ≤ _f_, then
        if k <= f {
            // i. Let _z_ be the String value consisting of _f_ + 1 - _k_ occurrences of the code unit 0x0030 (DIGIT ZERO).
            let z = "0".repeat((f + 1 - k) as usize);
            // ii. Set _m_ to the string-concatenation of _z_ and _m_.
            m = format!("{z}{m}");
            // iii. Set _k_ to _f_ + 1.
            k = f + 1;
        }
        // c. Let _a_ be the first _k_ - _f_ code units of _m_, and let _b_ be the remaining _f_ code units of _m_.
        let (a, b) = m.split_at((k - f) as usize);
        // e. Let _int_ be the length of _a_.
        int = a.len();
        // d. Set _m_ to the string-concatenation of _a_, *"."*, and _b_.
        m = format!("{a}.{b}");
    } else {
        // 8. Else,
        // a. Let _int_ be the length of _m_.
        int = m.len();
    }
    // 9. Let _cut_ be _maxFraction_ - _minFraction_.
    let mut cut = max_fraction - min_fraction;
    // 10. Repeat, while _cut_ > 0 and the last code unit of _m_ is 0x0030 (DIGIT ZERO),
    while cut > 0 && m.ends_with('0') {
        // a. Remove the last code unit from _m_.
        m.pop();
        // b. Set _cut_ to _cut_ - 1.
        cut -= 1;
    }
    // 11. If the last code unit of _m_ is 0x002E (FULL STOP), then
    if m.ends_with('.') {
        // a. Remove the last code unit from _m_.
        m.pop();
    }
    // 12. Return the Record { [[FormattedString]]: _m_, [[RoundedNumber]]: _xFinal_, [[IntegerDigitsCount]]: _int_, [[RoundingMagnitude]]: –_f_ }.
    Ok(RawResult {
        formatted_string: m,
        rounded_number: x_final,
        integer_digits_count: int,
        rounding_magnitude: -f,
    })
}

/// FormatNumericToString ( _intlObj_, _x_ )
///
/// _x_ is a mathematical value or ~negative-zero~.
pub(crate) fn format_numeric_to_string(
    agent: &mut Agent,
    intl_obj: &NumberFormatSlots,
    x: &IntlMV,
) -> JsResult<FormatNumericToStringResult> {
    use icu::decimal::input::{Decimal, SignDisplay};
    // 1. Assert: _intlObj_ has [[RoundingMode]], [[RoundingType]], [[MinimumSignificantDigits]], [[MaximumSignificantDigits]], [[MinimumIntegerDigits]], [[MinimumFractionDigits]], [[MaximumFractionDigits]], [[RoundingIncrement]], and [[TrailingZeroDisplay]] internal slots.
    let negative;
    let x: Decimal = match x {
        // 2. If _x_ is ~negative-zero~, then
        IntlMV::NegativeZero => {
            // a. Let _sign_ be ~negative~.
            negative = true;
            // b. Set _x_ to 0.
            Decimal::from(0u8)
        }
        // 3. Else,
        IntlMV::Finite { negative: neg, abs } => {
            // a. Assert: _x_ is a mathematical value.
            // b. If _x_ < 0, let _sign_ be ~negative~; else let _sign_ be ~positive~.
            negative = *neg;
            // c. If _sign_ is ~negative~, then
            //    i. Set _x_ to -_x_.
            abs.clone()
        }
        _ => return Err(agent.not_implemented("FormatNumericToString of NaN or an infinity")),
    };
    // 4. Let _unsignedRoundingMode_ be GetUnsignedRoundingMode(_intlObj_.[[RoundingMode]], _sign_).
    let Some(unsigned_rounding_mode) = get_unsigned_rounding_mode(&intl_obj.rounding_mode, negative)
    else {
        return Err(agent.throw_range_error("invalid roundingMode"));
    };
    let int = |v: Option<f64>| v.unwrap_or(0.0) as i64;
    let (min_sd, max_sd) = (
        int(intl_obj.minimum_significant_digits),
        int(intl_obj.maximum_significant_digits),
    );
    let (min_fd, max_fd) = (
        int(intl_obj.minimum_fraction_digits),
        int(intl_obj.maximum_fraction_digits),
    );
    let increment = intl_obj.rounding_increment as i64;
    let result = match intl_obj.rounding_type {
        // 5. If _intlObj_.[[RoundingType]] is ~significant-digits~, then
        RoundingType::SignificantDigits => {
            // a. Let _result_ be ToRawPrecision(...).
            to_raw_precision(agent, &x, min_sd, max_sd, unsigned_rounding_mode)?
        }
        // 6. Else if _intlObj_.[[RoundingType]] is ~fraction-digits~, then
        RoundingType::FractionDigits => {
            // a. Let _result_ be ToRawFixed(...).
            to_raw_fixed(agent, &x, min_fd, max_fd, increment, unsigned_rounding_mode)?
        }
        // 7. Else,
        RoundingType::MorePrecision | RoundingType::LessPrecision => {
            // a. Let _significantResult_ be ToRawPrecision(...).
            let significant_result =
                to_raw_precision(agent, &x, min_sd, max_sd, unsigned_rounding_mode)?;
            // b. Let _fractionResult_ be ToRawFixed(...).
            let fraction_result =
                to_raw_fixed(agent, &x, min_fd, max_fd, increment, unsigned_rounding_mode)?;
            // c. If _fractionResult_.[[RoundingMagnitude]] < _significantResult_.[[RoundingMagnitude]], let _fixedIsMorePrecise_ be *true*; else let _fixedIsMorePrecise_ be *false*.
            let fixed_is_more_precise =
                fraction_result.rounding_magnitude < significant_result.rounding_magnitude;
            if intl_obj.rounding_type == RoundingType::MorePrecision && fixed_is_more_precise {
                // d. If _intlObj_.[[RoundingType]] is ~more-precision~ and _fixedIsMorePrecise_ is *true*, then
                //    i. Let _result_ be _fractionResult_.
                fraction_result
            } else if intl_obj.rounding_type == RoundingType::LessPrecision && !fixed_is_more_precise {
                // e. Else if _intlObj_.[[RoundingType]] is ~less-precision~ and _fixedIsMorePrecise_ is *false*, then
                //    i. Let _result_ be _fractionResult_.
                fraction_result
            } else {
                // f. Else,
                //    i. Let _result_ be _significantResult_.
                significant_result
            }
        }
    };
    // 8. Set _x_ to _result_.[[RoundedNumber]].
    let mut x = result.rounded_number;
    // 9. Let _string_ be _result_.[[FormattedString]].
    let mut string = result.formatted_string;
    // 10. If _intlObj_.[[TrailingZeroDisplay]] is *"stripIfInteger"* and _x_ modulo 1 = 0, then
    let is_integer = x.is_zero() || x.nonzero_magnitude_end() >= 0;
    if intl_obj.trailing_zero_display == "stripIfInteger" && is_integer {
        // a. Let _i_ be StringIndexOf(_string_, *"."*, 0).
        // b. If _i_ is not ~not-found~, set _string_ to the substring of _string_ from 0 to _i_.
        if let Some(i) = string.find('.') {
            string.truncate(i);
        }
    }
    // 11. Let _int_ be _result_.[[IntegerDigitsCount]].
    let int = result.integer_digits_count;
    // 12. Let _minIntDigits_ be _intlObj_.[[MinimumIntegerDigits]].
    let min_int_digits = intl_obj.minimum_integer_digits as usize;
    // 13. If _int_ < _minIntDigits_, then
    if int < min_int_digits {
        // a. Let _forwardZeros_ be the String consisting of _minIntDigits_ - _int_ occurrences of the code unit 0x0030 (DIGIT ZERO).
        let forward_zeros = "0".repeat(min_int_digits - int);
        // b. Set _string_ to the string-concatenation of _forwardZeros_ and _string_.
        string = format!("{forward_zeros}{string}");
    }
    // 14. If _sign_ is ~negative~, then
    x.apply_sign_display(SignDisplay::Never);
    let rounded_number = if negative {
        // a. If _x_ is 0, set _x_ to ~negative-zero~. Otherwise, set _x_ to -_x_.
        IntlMV::finite(true, x)
    } else {
        IntlMV::Finite { negative: false, abs: x }
    };
    // 15. Return the Record { [[RoundedNumber]]: _x_, [[FormattedString]]: _string_ }.
    Ok(FormatNumericToStringResult {
        rounded_number,
        formatted_string: string,
    })
}

/// The digits, signs and separators of the number format's locale, read
/// from ICU4X by formatting probe values.
struct NumberSymbols {
    formatter: icu::decimal::DecimalFormatter,
    digits: Vec<char>,
    minus_sign: String,
    plus_sign: String,
}

fn number_symbols(agent: &mut Agent, nf: &NumberFormatSlots) -> JsResult<NumberSymbols> {
    use icu::decimal::input::{Decimal, SignDisplay};
    use icu::decimal::options::{DecimalFormatterOptions, GroupingStrategy};
    use icu::decimal::{DecimalFormatter, DecimalFormatterPreferences};
    use icu::locale::extensions::unicode::{Value as UValue, key};

    let Ok(mut locale) = icu::locale::Locale::try_from_str(&nf.locale) else {
        return Err(agent.not_implemented("Intl.NumberFormat: locale ICU4X cannot parse"));
    };
    if let Ok(nu) = UValue::try_from_str(&nf.numbering_system) {
        locale.extensions.unicode.keywords.set(key!("nu"), nu);
    }
    let mut options = DecimalFormatterOptions::default();
    options.grouping_strategy = Some(match nf.use_grouping.as_deref() {
        Some("always") => GroupingStrategy::Always,
        Some("min2") => GroupingStrategy::Min2,
        Some(_) => GroupingStrategy::Auto,
        None => GroupingStrategy::Never,
    });
    let formatter = DecimalFormatter::try_new(DecimalFormatterPreferences::from(&locale), options)
        .map_err(|_| agent.not_implemented("Intl.NumberFormat: ICU4X has no decimal symbols"))?;
    // The ten digits of the numbering system, from formatting 0123456789.
    let probe = Decimal::from(123456789u32);
    let _ = probe;
    let digit_probe = Decimal::try_from_str("9876543210")
        .map_err(|_| agent.not_implemented("Intl.NumberFormat: digits"))?;
    let mut ungrouped = DecimalFormatterOptions::default();
    ungrouped.grouping_strategy = Some(GroupingStrategy::Never);
    let plain = DecimalFormatter::try_new(DecimalFormatterPreferences::from(&locale), ungrouped)
        .map_err(|_| agent.not_implemented("Intl.NumberFormat: ICU4X has no decimal symbols"))?;
    let digits: Vec<char> = plain.format_to_string(&digit_probe).chars().collect();
    let sign_of = |display: SignDisplay, negative: bool| -> String {
        let text = if negative { "-1" } else { "1" };
        let mut d = Decimal::try_from_str(text).unwrap_or_default();
        d.apply_sign_display(display);
        plain
            .format_to_string(&d)
            .chars()
            .filter(|c| !digits.contains(c))
            .collect()
    };
    let minus_sign = sign_of(SignDisplay::Auto, true);
    let plus_sign = sign_of(SignDisplay::Always, false);
    Ok(NumberSymbols {
        formatter,
        digits,
        minus_sign,
        plus_sign,
    })
}

/// PartitionNumberPattern ( _numberFormat_, _x_ )
pub(crate) fn partition_number_pattern(
    agent: &mut Agent,
    number_format: &NumberFormatSlots,
    x: &IntlMV,
) -> JsResult<Vec<(String, String)>> {
    // 1. Let _exponent_ be 0.
    // 2. If _x_ is ~not-a-number~, then
    // 3. Else if _x_ is ~positive-infinity~, then
    // 4. Else if _x_ is ~negative-infinity~, then
    //    The ILD strings for NaN and the infinities are not in ICU4X's decimal data.
    if matches!(
        x,
        IntlMV::NotANumber | IntlMV::PositiveInfinity | IntlMV::NegativeInfinity
    ) {
        return Err(agent.not_implemented("Intl.NumberFormat: NaN and infinity symbols (ICU4X has no data)"));
    }
    if number_format.style != "decimal" {
        return Err(agent.not_implemented(&format!(
            "Intl.NumberFormat style {:?}: ICU4X percent, currency and unit patterns",
            number_format.style
        )));
    }
    if number_format.notation != "standard" {
        return Err(agent.not_implemented(&format!(
            "Intl.NumberFormat notation {:?}: ComputeExponent and ICU4X compact/scientific patterns",
            number_format.notation
        )));
    }
    // 5. Else,
    //    a. If _x_ is not ~negative-zero~, then
    //       (style is not "percent"; _exponent_ is 0 for standard notation)
    //    b. Let _formatNumberResult_ be FormatNumericToString(_numberFormat_, _x_).
    let format_number_result = format_numeric_to_string(agent, number_format, x)?;
    //    c. Let _formattedString_ be _formatNumberResult_.[[FormattedString]].
    let formatted_string = format_number_result.formatted_string;
    //    d. Set _x_ to _formatNumberResult_.[[RoundedNumber]].
    let x = format_number_result.rounded_number;
    // 6. Let _pattern_ be GetNumberFormatPattern(_numberFormat_, _x_).
    //    The decimal pattern is "{number}" with the sign of signDisplay in front.
    let (is_negative, is_zero) = match &x {
        IntlMV::NegativeZero => (true, true),
        IntlMV::Finite { negative, abs } => (*negative, abs.is_zero()),
        _ => (false, false),
    };
    let sign = match (number_format.sign_display.as_str(), is_negative, is_zero) {
        ("never", _, _) => None,
        ("auto", true, _) => Some("minusSign"),
        ("auto", false, _) => None,
        ("always", true, _) => Some("minusSign"),
        ("always", false, _) => Some("plusSign"),
        ("exceptZero", _, true) => None,
        ("exceptZero", true, false) => Some("minusSign"),
        ("exceptZero", false, false) => Some("plusSign"),
        ("negative", true, false) => Some("minusSign"),
        ("negative", _, _) => None,
        _ => return Err(agent.throw_range_error("invalid signDisplay")),
    };
    // 7. Let _result_ be a new empty List.
    let mut result: Vec<(String, String)> = Vec::new();
    // 8. Let _patternParts_ be PartitionPattern(_pattern_).
    // 9. For each Record { [[Type]], [[Value]] } _patternPart_ of _patternParts_, do
    let symbols = number_symbols(agent, number_format)?;
    // d./e. "plusSign" / "minusSign": the ILND String representing the sign.
    match sign {
        Some("minusSign") => result.push(("minusSign".into(), symbols.minus_sign.clone())),
        Some(_) => result.push(("plusSign".into(), symbols.plus_sign.clone())),
        None => {}
    }
    // c. Else if _partType_ is *"number"*, then
    //    i. Let _notationSubParts_ be PartitionNotationSubPattern(_numberFormat_, _x_, _formattedString_, _exponent_).
    let number = icu::decimal::input::Decimal::try_from_str(&formatted_string)
        .map_err(|_| agent.not_implemented("Intl.NumberFormat: formatted digits"))?;
    let localized = symbols.formatter.format_to_string(&number);
    // The fraction digits are the digits after the "." of _formattedString_.
    let fraction_count = formatted_string
        .split_once('.')
        .map_or(0, |(_, f)| f.chars().count());
    let total_digits = localized.chars().filter(|c| symbols.digits.contains(c)).count();
    let integer_count = total_digits.saturating_sub(fraction_count);
    let (mut seen, mut run, mut run_is_integer) = (0usize, String::new(), true);
    let mut flush = |run: &mut String, integer: bool, result: &mut Vec<(String, String)>| {
        if !run.is_empty() {
            let kind = if integer { "integer" } else { "fraction" };
            result.push((kind.into(), std::mem::take(run)));
        }
    };
    for c in localized.chars() {
        if symbols.digits.contains(&c) {
            run_is_integer = seen < integer_count;
            run.push(c);
            seen += 1;
        } else {
            flush(&mut run, run_is_integer, &mut result);
            // The separator right after the last integer digit is the decimal
            // separator when there are fraction digits; others are groups.
            let kind = if fraction_count > 0 && seen == integer_count {
                "decimal"
            } else {
                "group"
            };
            result.push((kind.into(), c.to_string()));
        }
    }
    flush(&mut run, run_is_integer, &mut result);
    // 10. Return _result_.
    Ok(result)
}

/// FormatNumeric ( _numberFormat_, _x_ )
pub(crate) fn format_numeric(
    agent: &mut Agent,
    number_format: &NumberFormatSlots,
    x: &IntlMV,
) -> JsResult<String> {
    // 1. Let _parts_ be PartitionNumberPattern(_numberFormat_, _x_).
    let parts = partition_number_pattern(agent, number_format, x)?;
    // 2. Let _result_ be the empty String.
    let mut result = String::new();
    // 3. For each Record { [[Type]], [[Value]] } _part_ of _parts_, do
    for (_, value) in parts {
        // a. Set _result_ to the string-concatenation of _result_ and _part_.[[Value]].
        result.push_str(&value);
    }
    // 4. Return _result_.
    Ok(result)
}
